/*
 * Make a new monster with the type controlled by the user.
 *
 * Note:  when creating a monster by class letter, specifying the
 * "strange object" (']') symbol produces a random monster rather
 * than a mimic.  This behavior quirk is useful so don't "fix" it
 * (use 'm'--or "mimic"--to create a random mimic).
 *
 * Used in wizard mode only (for ^G command and for scroll or spell
 * of create monster).  Once upon a time, an earlier incarnation of
 * this code was also used for the scroll/spell in explore mode.
 */
/**
 * @returns {Promise<number>} boolean
 */
export async function create_particular() {   // read.c:3372
    let d = new $T._create_particular_data(), buf = new Int8Array(256), prompt = new Int8Array(128);
    let tryct = CP_TRYLIM;
    let altmsg = 0;
    buf[0] = 0;   /* for EDIT_GETLIN */
    $c.strcpy(new $c.Ptr(prompt, 0), $C`Create what kind of monster?`);
    do {
        await getlin(new $c.Ptr(prompt, 0), new $c.Ptr(buf, 0));
        const bufp = mungspaces(new $c.Ptr(buf, 0));
        if (bufp.get(0) === 27) {
            return FALSE;
        }
        if (await create_particular_parse(bufp, d)) {
            break;
        }
        /* no good; try again... */
        if (bufp.get(0) || altmsg || tryct < 2) {
            await pline($C`I've never heard of such monsters.`);
        } else {
            await pline($C`Try again (type * for random, ESC to cancel).`);
            altmsg = altmsg + 1 | 0;
        }
        /* when a second try is needed, expand the prompt */
        if (tryct === CP_TRYLIM) {
            $c.strcat(new $c.Ptr(prompt, 0), $C` [type name or symbol]`);
        }
    } while ((tryct = tryct - 1 | 0) > 0);
    if (!tryct) {
        await pline($C`%s`, c_common_strings.c_thats_enough_tries);
    } else {
        return await create_particular_creation(d);
    }
    return FALSE;
}
